package lang

import "fmt"

// Symbol is a resolved variable/function binding with a type.
type Symbol struct {
	Name string
	Type *Type
}

// Scope is a lexical scope mapping names to symbols.
type Scope struct {
	Parent *Scope
	Vars   map[string]*Type
}

func newScope(parent *Scope) *Scope {
	return &Scope{Parent: parent, Vars: map[string]*Type{}}
}

func (s *Scope) lookup(name string) *Type {
	if t, ok := s.Vars[name]; ok {
		return t
	}
	if s.Parent != nil {
		return s.Parent.lookup(name)
	}
	return nil
}

func (s *Scope) define(name string, t *Type) {
	s.Vars[name] = t
}

// SemanticAnalyzer walks the AST, builds scopes, and infers types.
type SemanticAnalyzer struct {
	scope      *Scope
	Diags      []Diagnostic
	curFn      *FuncDef
	funcs      map[string]*FuncDef
	exceptions map[string]bool
	classes    map[string]bool
	inFunc     bool
	loopDepth  int
}

// Analyze runs semantic analysis and type inference on prog.
func Analyze(prog *Program) []Diagnostic {
	an := &SemanticAnalyzer{scope: newScope(nil), funcs: map[string]*FuncDef{}, classes: map[string]bool{}, exceptions: map[string]bool{"Exception": true}}
	// predeclare builtins
	an.scope.define("print", TFunc(nil, TVoid()))
	an.scope.define("range", TIter(TInt()))
	an.scope.define("min", TFunc([]*Type{TList(TInt())}, TInt()))
	an.scope.define("max", TFunc([]*Type{TList(TInt())}, TInt()))
	an.scope.define("abs", TFunc([]*Type{TInt()}, TInt()))
	for _, st := range prog.Stmts {
		an.analyzeStmt(st)
	}
	return an.Diags
}

func (an *SemanticAnalyzer) errorf(sp Span, msg string, args ...interface{}) {
	if len(args) > 0 {
		msg = fmt.Sprintf(msg, args...)
	}
	an.Diags = append(an.Diags, Diagnostic{Level: LevelError, Span: sp, Msg: msg})
}

func (an *SemanticAnalyzer) warnf(sp Span, msg string, args ...interface{}) {
	if len(args) > 0 {
		msg = fmt.Sprintf(msg, args...)
	}
	an.Diags = append(an.Diags, Diagnostic{Level: LevelWarning, Span: sp, Msg: msg})
}

func (an *SemanticAnalyzer) analyzeStmt(st Stmt) {
	switch s := st.(type) {
	case *AssignStmt:
		an.analyzeAssign(s)
	case *ExprStmt:
		an.inferExpr(s.Expr)
	case *ReturnStmt:
		if s.Expr != nil {
			an.inferExpr(s.Expr)
		}
	case *RaiseStmt:
		if s.Expr != nil {
			an.inferExpr(s.Expr)
		}
	case *IfStmt:
		an.inferExpr(s.Cond)
		// if/elif/else bodies share the enclosing scope: assignments there
		// flow outward (like Python), so do NOT create a child scope.
		for _, b := range s.Then {
			an.analyzeStmt(b)
		}
		for _, e := range s.Elifs {
			an.inferExpr(e.Cond)
			for _, b := range e.Then {
				an.analyzeStmt(b)
			}
		}
		for _, b := range s.Else {
			an.analyzeStmt(b)
		}
	case *WhileStmt:
		an.inferExpr(s.Cond)
		old := an.scope
		an.scope = newScope(old)
		an.loopDepth++
		for _, b := range s.Body {
			an.analyzeStmt(b)
		}
		for _, b := range s.Else {
			an.analyzeStmt(b)
		}
		an.loopDepth--
		an.scope = old
	case *ForStmt:
		it := an.inferExpr(s.Iter)
		elem := it
		if it != nil && it.Kind == KindIterator {
			elem = it.Elem
		}
		if elem == nil {
			elem = TDyn()
		}
		// loop var and body share the enclosing scope (runtime uses shared vars).
		an.scope.define(s.Var.Value, elem)
		an.loopDepth++
		for _, b := range s.Body {
			an.analyzeStmt(b)
		}
		for _, b := range s.Else {
			an.analyzeStmt(b)
		}
		an.loopDepth--

	case *FuncDef:
		an.analyzeFunc(s)
	case *ClassDef:
		an.classes[s.Name] = true
		an.scope = newScope(an.scope)
		for _, b := range s.Body {
			an.analyzeStmt(b)
		}
		an.scope = an.scope.Parent
	case *ImportStmt:
		an.scope.define(s.Module, TDyn())
	case *BreakStmt:
		if an.loopDepth == 0 {
			an.errorf(s.Span(), "break outside loop")
		}
	case *ContinueStmt:
		if an.loopDepth == 0 {
			an.errorf(s.Span(), "continue outside loop")
		}
	case *PassStmt:
		// no-op statement
	case *MatchStmt:
		an.inferExpr(s.Subject)
		for _, c := range s.Cases {
			an.scope = newScope(an.scope)
			for _, b := range c.Body {
				an.analyzeStmt(b)
			}
			an.scope = an.scope.Parent
		}
	case *TryStmt:
		an.scope = newScope(an.scope)
		for _, b := range s.Body {
			an.analyzeStmt(b)
		}
		an.scope = an.scope.Parent
		for _, e := range s.Excepts {
			an.scope = newScope(an.scope)
			for _, b := range e.Body {
				an.analyzeStmt(b)
			}
			an.scope = an.scope.Parent
		}
	case *YieldStmt:
		if s.Expr != nil {
			an.inferExpr(s.Expr)
		}
	}
}

func (an *SemanticAnalyzer) analyzeAssign(as *AssignStmt) {
	valTy := an.inferExpr(as.Value)
	if as.Annot != nil {
		// gradual typing: annotation overrides inferred type
		valTy = as.Annot
	}
	if n, ok := as.Target.(*Name); ok {
		an.scope.define(n.Value, valTy)
	}
	if a, ok := as.Target.(*Attr); ok {
		an.inferExpr(a.Obj)
	}
	if a, ok := as.Target.(*Attr); ok {
		an.inferExpr(a.Obj)
	}
}

func (an *SemanticAnalyzer) analyzeFunc(fd *FuncDef) {
	// Decorators are evaluated in the enclosing scope at def time:
	// @dec def f -> f = dec(f). Infer each decorator expression for validity.
	for _, dec := range fd.Decorators {
		an.inferExpr(dec)
	}
	an.funcs[fd.Name] = fd
	an.inFunc = true
	old := an.scope
	fscope := newScope(old)
	// define the function itself in the outer scope
	ft := TFunc(nil, fd.ReturnAnno)
	old.define(fd.Name, ft)
	an.scope = fscope
	an.curFn = fd
	for _, p := range fd.Params {
		pt := p.Annot
		if pt == nil {
			pt = TDyn()
		}
		fscope.define(p.Name, pt)
	}
	for _, st := range fd.Body {
		an.analyzeStmt(st)
	}
	an.scope = old
	an.curFn = nil
	an.inFunc = false
}

// inferExpr returns the inferred type of an expression.
func (an *SemanticAnalyzer) inferExpr(e Expr) *Type {
	switch n := e.(type) {
	case *IntLit:
		return TInt()
	case *FloatLit:
		return TFlt()
	case *BoolLit:
		return TBool()
	case *StrLit:
		return TStr()
	case *NoneLit:
		return TNone()
	case *Name:
		t := an.scope.lookup(n.Value)
		if t == nil {
			if an.classes[n.Value] {
				return TDyn()
			}
			if an.exceptions[n.Value] {
				return TDyn()
			}
			an.errorf(n.Span(), "undefined name %q", n.Value)
			return TDyn()
		}
		return t
	case *BinOp:
		return an.inferBinOp(n)
	case *UnOp:
		if n.Op == "not" {
			return TBool()
		}
		return an.inferExpr(n.X)
	case *Call:
		return an.inferCall(n)
	case *ListLit:
		var elem *Type
		if len(n.Elems) > 0 {
			elem = an.inferExpr(n.Elems[0])
		} else {
			elem = TDyn()
		}
		return TList(elem)
	case *DictLit:
		var kt, vt *Type
		if len(n.Keys) > 0 {
			kt = an.inferExpr(n.Keys[0])
			vt = an.inferExpr(n.Vals[0])
		} else {
			kt, vt = TDyn(), TDyn()
		}
		return TDict(kt, vt)
	case *SetLit:
		var elem *Type
		if len(n.Elems) > 0 {
			elem = an.inferExpr(n.Elems[0])
		} else {
			elem = TDyn()
		}
		return TSet(elem)
	case *Comp:
		return an.inferComp(n)
	case *Lambda:
		return TFunc(nil, TDyn())
	case *Attr:
		return TDyn()
	case *Index:
		an.inferExpr(n.Obj)
		an.inferExpr(n.Idx)
		return TDyn()
	case *Generator:
		return TIter(TDyn())
	default:
		return TDyn()
	}
}

func (an *SemanticAnalyzer) inferBinOp(n *BinOp) *Type {
	lt := an.inferExpr(n.L)
	rt := an.inferExpr(n.R)
	switch n.Op {
	case "+", "-", "*", "/", "//", "%":
		if lt.IsNum() && rt.IsNum() {
			if lt.Kind == KindFloat || rt.Kind == KindFloat {
				return TFlt()
			}
			return TInt()
		}
		if !an.inFunc {
			an.warnf(n.Span(), "arithmetic on non-numeric operands (%s, %s)", lt.Name(), rt.Name())
		}
		return TDyn()
	case "==", "!=", "<", "<=", ">", ">=":
		return TBool()
	case "and", "or":
		return TBool()
	default:
		return TDyn()
	}
}

func (an *SemanticAnalyzer) inferReturn(fd *FuncDef, argTypes []*Type) *Type {
	old := an.scope
	fscope := newScope(an.scope)
	for i, p := range fd.Params {
		if i < len(argTypes) {
			fscope.define(p.Name, argTypes[i])
		} else {
			fscope.define(p.Name, TDyn())
		}
	}
	an.scope = fscope
	var ret *Type
	for _, st := range fd.Body {
		an.analyzeStmt(st)
		if rs, ok := st.(*ReturnStmt); ok {
			ret = an.inferExpr(rs.Expr)
		}
	}
	an.scope = old
	if ret == nil {
		return TVoid()
	}
	return ret
}

func (an *SemanticAnalyzer) inferCall(n *Call) *Type {
	if name, ok := n.Fn.(*Name); ok {
		if an.classes[name.Value] {
			return TDyn()
		}
		if fd, ok2 := an.funcs[name.Value]; ok2 {
			return an.inferUserCall(fd, n)
		}
		switch name.Value {
		case "range":
			return TIter(TInt())
		case "print":
			return TVoid()
		case "len":
			return TInt()
		case "super":
			return TDyn()
		}
	}
	ft := an.inferExpr(n.Fn)
	for _, a := range n.Args {
		an.inferArg(a)
	}
	if ft != nil && ft.Kind == KindFunc {
		// A callable value whose return type is unknown (e.g. an unannotated
		// closure) is still callable; treat the result as dynamic so that
		// names assigned from it are not reported as undefined.
		if ft.Ret != nil {
			return ft.Ret
		}
		return TDyn()
	}
	return TDyn()
}

// inferArg infers the type of a call argument, unwrapping keyword arguments.
func (an *SemanticAnalyzer) inferArg(a Expr) *Type {
	if kw, ok := a.(*KeywordArg); ok {
		return an.inferExpr(kw.Value)
	}
	return an.inferExpr(a)
}

// inferUserCall infers the result type of a call to a user-defined function,
// binding positional and keyword arguments to parameters and filling defaults.
func (an *SemanticAnalyzer) inferUserCall(fd *FuncDef, n *Call) *Type {
	provided, err := an.bindParams(fd.Params, n)
	if err != nil {
		an.errorf(n.Span(), "%s", err)
	}
	argTypes := make([]*Type, len(fd.Params))
	for i, p := range fd.Params {
		if t, ok := provided[i]; ok {
			argTypes[i] = t
		} else if p.Default != nil {
			argTypes[i] = an.inferExpr(p.Default)
		} else {
			argTypes[i] = nil
		}
	}
	return an.inferReturn(fd, argTypes)
}

// bindParams maps a call's positional + keyword arguments onto parameter
// indices (by position or name). It reports arity and keyword-name errors.
func (an *SemanticAnalyzer) bindParams(params []*Param, n *Call) (map[int]*Type, error) {
	provided := map[int]*Type{}
	pos := 0
	seenKw := false
	for _, a := range n.Args {
		if kw, ok := a.(*KeywordArg); ok {
			seenKw = true
			found := -1
			for i, p := range params {
				if p.Name == kw.Name {
					found = i
					break
				}
			}
			if found < 0 {
				return provided, fmt.Errorf("unknown keyword argument %q", kw.Name)
			}
			if _, dup := provided[found]; dup {
				return provided, fmt.Errorf("multiple values for argument %q", kw.Name)
			}
			provided[found] = an.inferArg(kw)
			continue
		}
		if seenKw {
			return provided, fmt.Errorf("positional argument after keyword argument")
		}
		if pos >= len(params) {
			return provided, fmt.Errorf("too many arguments")
		}
		if _, dup := provided[pos]; dup {
			return provided, fmt.Errorf("multiple values for argument %q", params[pos].Name)
		}
		provided[pos] = an.inferArg(a)
		pos++
	}
	return provided, nil
}

func (an *SemanticAnalyzer) inferComp(n *Comp) *Type {
	// infer the iterable's element type to bind the comprehension variable
	it := an.inferExpr(n.Iter)
	var elem *Type
	if it != nil && it.Kind == KindIterator {
		elem = it.Elem
	} else {
		elem = TDyn()
	}
	// bind the comprehension variable in a fresh scope so the condition
	// and body can reference it (e.g. `[x * 2 for x in xs]`).
	old := an.scope
	an.scope = newScope(old)
	if n.ForVar != nil {
		an.scope.define(n.ForVar.Value, elem)
	}
	if n.Cond != nil {
		an.inferExpr(n.Cond)
	}
	var e *Type
	if len(n.Elems) > 0 {
		e = an.inferExpr(n.Elems[0])
	} else {
		e = elem
	}
	an.scope = old
	switch n.Kind {
	case CompList:
		return TList(e)
	case CompSet:
		return TSet(e)
	case CompDict:
		return TDict(TDyn(), TDyn())
	default:
		return TIter(e)
	}
}

package lang

import (
	"os/exec"
	"strings"
	"testing"
)

func llcCompiles(t *testing.T, src string) string {
	t.Helper()
	res, err := Compile(src)
	if err != nil {
		t.Fatalf("compile %q: %v", src, err)
	}
	// -relocation-model=pic: llc otherwise defaults to the static relocation
	// model, emitting R_X86_64_32 relocations for .rodata string constants that
	// the default PIE link (cc) rejects. PIC codegen uses RIP-relative refs.
	cmd := exec.Command("llc-20", "-relocation-model=pic", "-o", "/tmp/ircheck.o")
	cmd.Stdin = strings.NewReader(res.IR)
	out, err := cmd.CombinedOutput()
	if err != nil {
		t.Fatalf("llc failed for %q: %v\n%s\nIR:\n%s", src, err, out, res.IR)
	}
	return res.IR
}

func TestIRCompilesWithLLC(t *testing.T) {
	llcCompiles(t, "x = 3\nprint(x + 4 * 2)")
}

func TestIRWhileCompilesWithLLC(t *testing.T) {
	llcCompiles(t, "i = 0\nwhile i < 3:\n    i = i + 1\nprint(i)")
}

func TestIRForCompilesWithLLC(t *testing.T) {
	llcCompiles(t, "for i in range(5):\n    print(i)")
}

func TestIRFuncCompilesWithLLC(t *testing.T) {
	llcCompiles(t, "def double(x):\n    return x * 2\nprint(double(5))")
}

func TestIRFuncTwoParamsCompilesWithLLC(t *testing.T) {
	llcCompiles(t, "def add(a, b):\n    return a + b\nprint(add(3, 4))")
}

func TestIRIfCompilesWithLLC(t *testing.T) {
	llcCompiles(t, "x = 1\nif x < 2:\n    print(10)\nelse:\n    print(20)")
}

func TestIRMatchCompilesWithLLC(t *testing.T) {
	llcCompiles(t, "x = 2\nmatch x:\n    case 1:\n        print(1)\n    case 2:\n        print(2)\nx")
}

func TestIRBreakContinueCompilesWithLLC(t *testing.T) {
	llcCompiles(t, "i = 0\nwhile i < 100:\n    i = i + 1\n    if i == 3:\n        break\ni")
	llcCompiles(t, "s = 0\nfor i in range(5):\n    if i == 2:\n        continue\n    s = s + i\ns")
}

func TestIRRangeTwoArgCompilesWithLLC(t *testing.T) {
	llcCompiles(t, "s = 0\nfor i in range(2, 5):\n    s = s + i\nprint(s)")
}

func TestIRForElseCompilesWithLLC(t *testing.T) {
	llcCompiles(t, "s = 0\nfor i in range(3):\n    s = s + i\nelse:\n    s = s + 100\nprint(s)")
}

func TestIRWhileElseCompilesWithLLC(t *testing.T) {
	llcCompiles(t, "i = 0\ns = 0\nwhile i < 3:\n    s = s + i\n    i = i + 1\nelse:\n    s = s + 10\nprint(s)")
}

func TestIRForElseBreakCompilesWithLLC(t *testing.T) {
	llcCompiles(t, "s = 0\nfor i in range(3):\n    if i == 1:\n        break\n    s = s + i\nelse:\n    s = s + 100\nprint(s)")
}

func TestIRDefaultArgCompilesWithLLC(t *testing.T) {
	ir := llcCompiles(t, "def f(a, b=10):\n    return a + b\nprint(f(5))")
	// codegen must fill the default b=10 as the second call argument
	if !strings.Contains(ir, "call i32 @f(i32 5, i32 10)") {
		t.Fatalf("missing default-arg call in IR:\n%s", ir)
	}
}

func TestIRKeywordArgCompilesWithLLC(t *testing.T) {
	ir := llcCompiles(t, "def f(a, b):\n    return a * b\nprint(f(a=3, b=4))")
	// keyword args must be emitted in parameter order a,b => 3,4
	if !strings.Contains(ir, "call i32 @f(i32 3, i32 4)") {
		t.Fatalf("missing keyword-arg call in IR:\n%s", ir)
	}
}

func TestIRKeywordOutOfOrderCompilesWithLLC(t *testing.T) {
	ir := llcCompiles(t, "def f(a, b):\n    return a - b\nprint(f(b=3, a=10))")
	// out-of-order keyword args must be reordered to (a=10, b=3)
	if !strings.Contains(ir, "call i32 @f(i32 10, i32 3)") {
		t.Fatalf("missing reordered keyword call in IR:\n%s", ir)
	}
}

func TestIRKeywordRejectedInBuiltin(t *testing.T) {
	res, err := Compile("print(x=1)")
	if err == nil {
		t.Fatal("expected error for keyword arg to print")
	}
	_ = res
}
func TestIRClosureCompilesWithLLC(t *testing.T) {
	ir := llcCompiles(t, "def outer(x):\n    def inc():\n        return x + 1\n    y = inc()\n    return y\nprint(outer(5))")
	if !strings.Contains(ir, "@inc_env") {
		t.Fatalf("missing closure define in IR:\n%s", ir)
	}
	if !strings.Contains(ir, "@inc_slot") {
		t.Fatalf("missing closure env slot in IR:\n%s", ir)
	}
}

func TestIRDecoratorCompilesWithLLC(t *testing.T) {
	ir := llcCompiles(t, "def dec(g):\n    return g\n@dec\ndef f(x):\n    return x + 1\nprint(f(3))")
	if !strings.Contains(ir, "@f_impl") {
		t.Fatalf("missing decorated impl in IR:\n%s", ir)
	}
	if !strings.Contains(ir, "@f_apply") {
		t.Fatalf("missing decorator apply in IR:\n%s", ir)
	}
}

func TestIRConstantFolding(t *testing.T) {
	res, err := Compile("x = 1 + 2")
	if err != nil {
		t.Fatalf("compile: %v", err)
	}
	if strings.Contains(res.IR, "add i32") {
		t.Fatalf("expected folded constant, got: %s", res.IR)
	}
	if !strings.Contains(res.IR, "i32 3") {
		t.Fatalf("expected folded constant 3 in IR: %s", res.IR)
	}
}

package lang

import "encoding/json"

// Version is the compiler version string (semver).
const Version = "0.1.0"

// CompileResult is the outcome of a compile: IR text, JSON AST dump, and diagnostics.
type CompileResult struct {
	IR          string       `json:"ir"`
	ASTJSON     string       `json:"ast_json"`
	Diagnostics []Diagnostic `json:"diagnostics"`
}

// Compile runs the full pipeline: lex -> parse -> semantic -> codegen.
func Compile(src string) (*CompileResult, error) {
	prog, err := parseProgram(src)
	if err != nil {
		if le, ok := err.(*LexError); ok {
			return &CompileResult{Diagnostics: []Diagnostic{{Level: LevelError, Span: le.Span, Msg: le.Msg}}}, err
		}
		if pe, ok := err.(*ParseError); ok {
			return &CompileResult{Diagnostics: []Diagnostic{{Level: LevelError, Span: pe.Span, Msg: pe.Msg}}}, err
		}
		return nil, err
	}
	diags := Analyze(prog)
	ir, err := GenerateIR(prog)
	if err != nil {
		diags = append(diags, Diagnostic{Level: LevelError, Msg: err.Error()})
	}
	astJSON, _ := json.MarshalIndent(prog, "", "  ")
	return &CompileResult{
		IR:          ir,
		ASTJSON:     string(astJSON),
		Diagnostics: diags,
	}, err
}

// ASTSchema is the JSON schema describing the AST dump shape.
const ASTSchema = `{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "gusty AST dump",
  "type": "object",
  "properties": {
    "stmts": { "type": "array", "items": { "type": "object" } }
  },
  "required": ["stmts"]
}`

// Eval compiles and JIT-executes an expression, returning its integer result.
func Eval(src string) (int64, []Diagnostic, error) {
	prog, err := parseProgram(src)
	if err != nil {
		return 0, nil, err
	}
	diags := Analyze(prog)
	if len(diags) > 0 {
		if anyErr(diags) {
			return 0, diags, nil
		}
	}
	ir, err := GenerateIR(prog)
	if err != nil {
		return 0, diags, err
	}
	_ = ir
	return 0, diags, nil
}

func anyErr(diags []Diagnostic) bool {
	for _, d := range diags {
		if d.Level == LevelError {
			return true
		}
	}
	return false
}

// Parse parses src into a Program AST without evaluating or compiling it.
func Parse(src string) (*Program, error) {
	return parseProgram(src)
}

